import 'package:location/location.dart';import 'package:geocoding/geocoding.dart' as geocoding;class LocationService {  Location location = Location();   Future<void> checkAndRequestLocationService() async {    var isServiceEnabled = await location.serviceEnabled();    if (!isServiceEnabled) {      isServiceEnabled = await location.requestService();      if (!isServiceEnabled) {        throw LocationServiceException();      }    }  }  Future<void> checkAndRequestLocationPermission() async {    var permissionStatus = await location.hasPermission();    if (permissionStatus == PermissionStatus.deniedForever) {      throw LocationPermissionException();    }    if (permissionStatus == PermissionStatus.denied) {      permissionStatus = await location.requestPermission();      if (permissionStatus != PermissionStatus.granted) {        throw LocationPermissionException();      }    }  }  void getRealTimeLocationData(void Function(LocationData)? onData) async {    await checkAndRequestLocationService();    await checkAndRequestLocationPermission();    location.onLocationChanged.listen(onData);  }  Future<LocationData> getLocation() async {    await checkAndRequestLocationService();    await checkAndRequestLocationPermission();    return await location.getLocation();  }  Future<void> getDetailsAddressByLatLong() async {    var data = await location.getLocation();  // Get latitude & longitude    try {      // print(data.latitude!);      // print(data.longitude!);      List<geocoding.Placemark> placeMark = await geocoding.placemarkFromCoordinates(          data.latitude!,          data.longitude!      );      if (placeMark.isNotEmpty) {        // geocoding.placeMark place = PlaceMarks.first;        // print("City: ${place.locality}");        // print("Country: ${place.country}");        // print("Postal Code: ${place.postalCode}");        // print("Administrative Area: ${place.administrativeArea}");        // print("Sub Administrative Area: ${place.subAdministrativeArea}");        // print("Thoroughfare: ${place.thoroughfare}");        // print("Sub Thoroughfare: ${place.subThoroughfare}");      }    } catch (e) {      // print("Error: $e");    }  }    Future<void> getDetailsAddressByAddress(String address) async {    // List<geocoding.Location> placeMarks = await geocoding.locationFromAddress(address);    // print(placeMarks);      }}class LocationServiceException implements Exception {}class LocationPermissionException implements Exception {}